1	/**
2	 * Deterministic development seed: two organizations on different plans, members in all four roles, projects, issues (including archived and overdue) and comments.
3	 *
4	 * Must call (do not reimplement): uniqueSlug, getPlanLimits
5	 */
6	import { getPlanLimits } from "@/config/plan-limits";
7	import { hashPassword } from "@/lib/hash";
8	import { idFactory } from "@/lib/id";
9	import { uniqueSlug } from "@/lib/slug";
10	import { getDb } from "@/server/db";
11	import {
12	  comments,
13	  issues,
14	  labels,
15	  members,
16	  organizationUsage,
17	  organizations,
18	  projects,
19	  subscriptions,
20	  users,
21	} from "@/server/db";
22	import { runMigrations } from "./migrate";
23	import type { IssuePriority, IssueStatus } from "@/types/issue";
24	import type { PlanId } from "@/types/billing";
25	import type { Role } from "@/types/member";
26	
27	export type SeedSummary = {
28	  organizations: number;
29	  users: number;
30	  projects: number;
31	  issues: number;
32	  comments: number;
33	};
34	
35	/**
36	 * Fixed epoch so every seeded row — and therefore every snapshot test built on
37	 * this data — has the same timestamps on every machine.
38	 */
39	const EPOCH = Date.UTC(2026, 0, 5, 9, 0, 0);
40	const MS_PER_DAY = 24 * 60 * 60 * 1000;
41	
42	/**
43	 * The password every seeded account shares. Sign in as
44	 * `owner@northwind.test` (or admin/member/viewer, and the same four on
45	 * `acme.test`) with this.
46	 */
47	export const SEED_PASSWORD = "taskflow-dev";
48	
49	/** Ids come from a seeded generator, so the whole fixture is reproducible. */
50	const nextId = idFactory(20_260_105);
51	
52	const ORG_SPECS: readonly {
53	  name: string;
54	  slug: string;
55	  plan: PlanId;
56	  projects: readonly { name: string; slug: string; key: string }[];
57	}[] = [
58	  {
59	    name: "Northwind Labs",
60	    slug: "northwind",
61	    plan: "growth",
62	    projects: [
63	      { name: "Platform", slug: "platform", key: "PLAT" },
64	      { name: "Mobile App", slug: "mobile-app", key: "MOB" },
65	    ],
66	  },
67	  {
68	    name: "Acme Robotics",
69	    slug: "acme",
70	    plan: "free",
71	    projects: [{ name: "Firmware", slug: "firmware", key: "FIRM" }],
72	  },
73	];
74	
75	const ROLE_SPECS: readonly { role: Role; name: string }[] = [
76	  { role: "owner", name: "Ada Owner" },
77	  { role: "admin", name: "Bo Admin" },
78	  { role: "member", name: "Cy Member" },
79	  { role: "viewer", name: "Di Viewer" },
80	];
81	
82	const STATUS_CYCLE: readonly IssueStatus[] = [
83	  "backlog",
84	  "todo",
85	  "in_progress",
86	  "in_review",
87	  "done",
88	];
89	
90	const PRIORITY_CYCLE: readonly IssuePriority[] = [
91	  "none",
92	  "low",
93	  "medium",
94	  "high",
95	  "urgent",
96	];
97	
98	/** Issues per project; two orgs × three projects gives roughly forty issues. */
99	const ISSUES_PER_PROJECT = 13;
100	
101	/**
102	 * Writes the fixture. Idempotent in the sense that it migrates first and then
103	 * clears every table it owns, so running it twice leaves the same database
104	 * rather than a doubled one.
105	 */
106	export async function seedDatabase(
107	  databasePath?: string,
108	): Promise<SeedSummary> {
109	  await runMigrations(databasePath);
110	
111	  const db = getDb(databasePath);
112	  const summary: SeedSummary = {
113	    organizations: 0,
114	    users: 0,
115	    projects: 0,
116	    issues: 0,
117	    comments: 0,
118	  };
119	
120	  clear();
121	
122	  // Hashed once and shared by all eight accounts: `verifyPassword` only
123	  // accepts the `scrypt:<salt>:<key>` shape this produces, so a literal
124	  // placeholder here would leave every seeded user unable to sign in. The
125	  // salt is random, which is the one field of the fixture that is not
126	  // reproducible across runs — deliberately, since a fixed salt in a seed is
127	  // the kind of thing that gets copied into a deployment.
128	  const seedPasswordHash = await hashPassword(SEED_PASSWORD);
129	
130	  const takenSlugs: string[] = [];
131	
132	  for (const [orgIndex, spec] of ORG_SPECS.entries()) {
133	    const slug = uniqueSlug(spec.slug, takenSlugs);
134	    takenSlugs.push(slug);
135	
136	    const orgId = nextId();
137	    const created = stamp(orgIndex);
138	    const limits = getPlanLimits(spec.plan);
139	
140	    const seededUsers = ROLE_SPECS.map((roleSpec, roleIndex) => {
141	      const userId = nextId();
142	      db.insert(users)
143	        .values({
144	          id: userId,
145	          email: `${roleSpec.role}@${slug}.test`,
146	          name: roleSpec.name,
147	          passwordHash: seedPasswordHash,
148	          avatarUrl: null,
149	          timezone: "UTC",
150	          emailVerifiedAt: created,
151	          createdAt: created,
152	          updatedAt: created,
153	        })
154	        .run();
155	      summary.users += 1;
156	
157	      db.insert(members)
158	        .values({
159	          id: nextId(),
160	          orgId,
161	          userId,
162	          role: roleSpec.role,
163	          status: "active",
164	          invitedBy: null,
165	          joinedAt: created,
166	          lastSeenAt: created,
167	          createdAt: created,
168	          updatedAt: created,
169	        })
170	        .run();
171	
172	      return { userId, role: roleSpec.role, index: roleIndex };
173	    });
174	
175	    const ownerId = seededUsers[0]?.userId ?? nextId();
176	
177	    db.insert(organizations)
178	      .values({
179	        id: orgId,
180	        name: spec.name,
181	        slug,
182	        ownerId,
183	        plan: spec.plan,
184	        logoUrl: null,
185	        trialEndsAt: null,
186	        digestHourUtc: 7 + orgIndex,
187	        enabledFlagOverrides: JSON.stringify(
188	          limits.includedFlags.slice(0, 1),
189	        ),
190	        createdAt: created,
191	        updatedAt: created,
192	      })
193	      .run();
194	    summary.organizations += 1;
195	
196	    db.insert(subscriptions)
197	      .values({
198	        id: nextId(),
199	        orgId,
200	        plan: spec.plan,
201	        interval: "monthly",
202	        status: "active",
203	        seats: seededUsers.length,
204	        currentPeriodStart: created,
205	        currentPeriodEnd: stamp(orgIndex + 30),
206	        cancelAt: null,
207	        createdAt: created,
208	        updatedAt: created,
209	      })
210	      .run();
211	
212	    const labelIds = ["bug", "feature", "chore"].map((name) => {
213	      const labelId = nextId();
214	      db.insert(labels)
215	        .values({
216	          id: labelId,
217	          orgId,
218	          name,
219	          color: "#94a3b8",
220	          description: null,
221	          createdAt: created,
222	          updatedAt: created,
223	        })
224	        .run();
225	      return labelId;
226	    });
227	    void labelIds;
228	
229	    for (const [projectIndex, projectSpec] of spec.projects.entries()) {
230	      const projectId = nextId();
231	
232	      db.insert(projects)
233	        .values({
234	          id: projectId,
235	          orgId,
236	          name: projectSpec.name,
237	          slug: projectSpec.slug,
238	          key: projectSpec.key,
239	          description: `${projectSpec.name} work for ${spec.name}`,
240	          visibility: projectIndex === 0 ? "org" : "private",
241	          status: "active",
242	          leadId: ownerId,
243	          color: "#6366f1",
244	          startsAt: created,
245	          targetDate: stamp(orgIndex + 60),
246	          createdAt: created,
247	          updatedAt: created,
248	        })
249	        .run();
250	      summary.projects += 1;
251	
252	      for (let n = 1; n <= ISSUES_PER_PROJECT; n += 1) {
253	        const issueId = nextId();
254	        const author = seededUsers[n % seededUsers.length];
255	        const assignee = seededUsers[(n + 1) % seededUsers.length];
256	        const status = STATUS_CYCLE[n % STATUS_CYCLE.length] ?? "backlog";
257	
258	        // Every fourth issue is archived and every fifth is overdue, so the
259	        // soft-delete filters and the overdue job both have data to find.
260	        const archived = n % 4 === 0;
261	        const overdue = n % 5 === 0;
262	
263	        db.insert(issues)
264	          .values({
265	            id: issueId,
266	            orgId,
267	            projectId,
268	            number: n,
